import {INTERESTS,DEFAULT_PROFILE,PEOPLE,DATE_TYPES,inferInterests,validateProfile,portrait,introduction,compare,makePlan,planText,calendar} from './engine.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({step:0,furthest:0,draft:structuredClone(DEFAULT_PROFILE),profile:null,personId:'xia',plan:null,options:defaultOptions(),feedback:''});
function defaultOptions(){const date=new Date();date.setDate(date.getDate()+1);return {type:'书店闲逛',duration:60,budget:80,date:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,time:'15:00',city:'成都'};}
let state=fresh();let toastTimer;const person=()=>PEOPLE.find(p=>p.id===state.personId);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function selectField(name,label,values,value){return `<label class="field"><span>${label}</span><select name="${name}" id="${name}">${values.map(v=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function exportFile(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制，可以先修改再分享。');}catch{exportFile('有共鸣-文案.txt',text);toast('无法访问剪贴板，已改为下载文案。');}}
function drawProfile(p){const t=portrait(p);return `<div class="profile-card"><div class="profile-top"><span class="avatar">${esc(p.name.slice(-1)||'你')}</span><div><strong>${esc(p.name||'你的称呼')}</strong><small>${esc(p.city)} · 根据你确认的选项整理</small></div></div><span class="x-label">MY X FACTOR / 一种表达</span><p class="x-line">${esc(t.x)}</p><div class="evidence-row"><span>可以一起做的事</span><p>${esc(t.activity)}</p></div><div class="evidence-row"><span>认真在意的事</span><p>${esc(t.relationship)}</p></div><div class="evidence-row"><span>需要坦诚交流</span><p>${esc(p.rhythm)} · ${esc(p.children)}</p></div><p class="profile-footer">这是一份表达草稿。最有权解释你的人，始终是你。</p></div>`;}
function readDraft(){const form=$('#profile-form');if(!form)return;for(const key of ['name','intro','city','rhythm','children','communication'])state.draft[key]=form.elements[key].value;}
function updatePreview(){readDraft();state.profile=null;state.plan=null;state.furthest=0;document.querySelectorAll('.step').forEach((b,i)=>b.disabled=i>0);$('#profile-preview').innerHTML=drawProfile(state.draft);$('#char-count').textContent=`${state.draft.intro.length} / 1200`;}
function drawInterests(){return INTERESTS.map(i=>`<button type="button" class="chip" data-interest="${i}" aria-pressed="${state.draft.interests.includes(i)}">${i}</button>`).join('');}
function renderProfile(){const p=state.draft;$('#app').innerHTML=`<div class="workspace reveal"><div class="editor"><p class="overline">01 / START WITH YOUR EVERYDAY</p><h3 tabindex="-1">先从一个平常的周末说起。</h3><p class="subtext">不用把自己写得完美。那些具体的小事，更能让人靠近。</p><form id="profile-form" novalidate><div class="row-fields"><label class="field"><span>怎么称呼你</span><input name="name" autocomplete="off" maxlength="16" value="${esc(p.name)}" required></label>${selectField('city','生活城市',['成都','上海','北京','广州','深圳','杭州','其他 / 未定'],p.city)}</div><div class="label-row"><label for="intro">你会怎么介绍自己？</label><button type="button" class="link-button" id="use-example">填入示例</button></div><textarea name="intro" id="intro" maxlength="1200" minlength="12" required>${esc(p.intro)}</textarea><div class="char-count" id="char-count">${p.intro.length} / 1200</div><div class="label-row"><span>你愿意分享的兴趣</span><button type="button" class="link-button" id="infer">从介绍中识别 ↗</button></div><div class="chips" id="interests">${drawInterests()}</div><p class="hint">点击选择或取消。文字识别只是提示，请亲自确认。</p><div class="row-fields">${selectField('rhythm','平时的作息',['偏早睡','偏晚睡','时间弹性'],p.rhythm)}${selectField('children','对孩子的想法',['希望养育孩子','不打算养育孩子','还没想好'],p.children)}</div>${selectField('communication','有分歧时，更倾向于',['愿意及时沟通','需要一点独处再聊','一起商量方式'],p.communication)}<div id="profile-error" class="error" role="alert"></div><div class="actions"><button class="button primary" type="submit">看看我们怎样相处 <span aria-hidden="true">→</span></button><button class="button secondary" type="button" id="copy-intro">复制我的介绍</button></div></form></div><aside class="preview"><p class="overline">A GLIMPSE OF YOU / 你的生活切片</p><div id="profile-preview">${drawProfile(p)}</div><p class="mini-note">把“我有什么”变成“和我在一起是什么感觉”。左侧的选择会实时更新这张画像。</p><div class="notice">自由介绍用于提示兴趣；画像文案由你确认的选项整理。原始介绍不会自动出现在导出文案中。</div></aside></div>`;
 $('#profile-form').addEventListener('input',updatePreview);$('#profile-form').addEventListener('change',updatePreview);
 $('#interests').onclick=e=>{const b=e.target.closest('[data-interest]');if(!b)return;const i=b.dataset.interest;state.draft.interests=state.draft.interests.includes(i)?state.draft.interests.filter(v=>v!==i):[...state.draft.interests,i];b.setAttribute('aria-pressed',String(state.draft.interests.includes(i)));updatePreview();};
 $('#infer').onclick=()=>{readDraft();state.draft.interests=inferInterests(state.draft.intro);$('#interests').innerHTML=drawInterests();updatePreview();toast(state.draft.interests.length?'识别完成，请核对或修改兴趣。':'没有识别到明确兴趣，可以手动选择。');};
 $('#use-example').onclick=()=>{state=fresh();render();toast('已填入虚构示例。');};
 $('#copy-intro').onclick=()=>{readDraft();try{copyText(introduction(validateProfile(state.draft)));}catch(e){$('#profile-error').textContent=e.message;}};
 $('#profile-form').onsubmit=e=>{e.preventDefault();readDraft();try{commitProfile(state.draft);navigate(1,true);}catch(error){$('#profile-error').textContent=error.message;}};
}
function commitProfile(p){const validated=validateProfile(p);state.profile=validated;state.draft=structuredClone(validated);state.plan=null;state.feedback='';state.furthest=1;state.options.city=validated.city===person().city?validated.city:'双方另行商量';return validated;}
function choosePerson(id){if(!PEOPLE.some(x=>x.id===id))throw new Error('示例人物不存在。');state.personId=id;state.plan=null;state.feedback='';state.furthest=1;state.options.city=state.profile.city===person().city?state.profile.city:'双方另行商量';const c=compare(state.profile,person());state.options.type=c.common.includes('阅读')?'书店闲逛':'散步与咖啡';renderMatch();return c;}
function renderMatch(){const p=state.profile,q=person(),c=compare(p,q);$('#app').innerHTML=`<div class="match-layout reveal"><div class="match-header"><div><p class="overline">02 / IMAGINE AN ORDINARY DAY</p><h3 tabindex="-1">${esc(p.name)}和${esc(q.name)}，会怎样相处？</h3><p class="subtext">${esc(c.statement)}</p></div><div class="candidate-tabs" aria-label="切换虚构人物">${PEOPLE.map(q=>`<button type="button" data-person="${q.id}" aria-pressed="${q.id===state.personId}"><span class="avatar ${q.tone}">${q.name.slice(-1)}</span><span>${q.name}<span>${q.city} · 虚构人物</span></span></button>`).join('')}</div></div><div class="match-columns"><aside class="person-summary"><div class="profile-top"><span class="avatar ${q.tone}">${q.name.slice(-1)}</span><div><strong>${q.name}</strong><small>虚构人物 · 用于探索不同相处情景</small></div></div><p class="x-line">${q.x}</p><p>${q.intro}</p><div class="facts">${q.interests.map(i=>`<span>${i}</span>`).join('')}</div><p class="hint" style="margin-top:20px;margin-bottom:0">没有真实用户池，也不会联系这位人物。</p></aside><div><div class="connection"><h4><span class="pill-label">好奇的起点</span>${c.common.length?'一起做点喜欢的事':'给不同的兴趣留一点空间'}</h4><p>${esc(c.shared)}</p><p class="source">依据：你确认的兴趣 × 示例人物自述</p></div><div class="connection"><h4><span class="pill-label">现实的条件</span>${c.sameCity?'同城，让见面更容易安排':'见面，需要先商量地点'}</h4><p>${c.sameCity?`你们目前都在${esc(p.city)}，可以先约一小时，给彼此一个轻松认识的机会。`:'先确认见面城市、时间和出行成本，再决定是否做计划。'}</p><p class="source">依据：双方填写的生活城市</p></div><div class="connection"><h4><span class="pill-label">关系的空间</span>了解差异，比猜中人设更有用</h4><p>共同爱好可以打开话题；是否愿意倾听、互相照顾，需要通过真实相处来了解。</p><p class="source">这是对话建议，不是关系成功率预测</p></div></div></div><div class="conversation-box"><h4>${c.hardConflict?'先认真看这些分歧':'见面之前，值得聊清楚'}</h4><ul>${c.issues.length?c.issues.map(i=>`<li><strong>${i.kind} · ${i.topic}：</strong>${esc(i.detail)}</li>`).join(''):'<li>已填写的选项暂未显示明显差异。仍需要聊聊消费习惯、家庭边界与未来计划。</li>'}</ul></div><div class="actions"><button type="button" class="button primary" id="to-plan">一起设计第一次见面 <span aria-hidden="true">→</span></button><button type="button" class="button secondary" id="back-profile">修改我的画像</button><button type="button" class="link-button" id="copy-match">复制相处提案</button></div></div>`;
 $('[data-person="xia"]').onclick=()=>choosePerson('xia');$('[data-person="zhou"]').onclick=()=>choosePerson('zhou');$('#back-profile').onclick=()=>navigate(0,true);$('#to-plan').onclick=()=>{state.furthest=2;navigate(2,true);};$('#copy-match').onclick=()=>copyText(`有共鸣｜${p.name} × ${q.name}（虚构人物）\n\n${c.shared}\n\n值得聊清楚：\n${c.issues.length?c.issues.map(i=>`${i.topic}：${i.detail}`).join('\n'):'进一步了解消费习惯、家庭边界和未来计划。'}\n\n这是一份对话提案，不是关系预测。`);
}
function planMarkup(plan){return `<div class="plan-card"><div class="plan-card-head"><p class="overline">OUR FIRST LITTLE PLAN</p><h4>${esc(plan.type)}，慢慢认识。</h4><div class="plan-meta">${esc(plan.date)} · ${esc(plan.time)} · ${plan.duration} 分钟<br>${esc(plan.city)} · 每人预算参考 ≤ ¥${plan.budget}</div></div><div class="plan-body">${plan.timeline.map(t=>`<div class="timeline"><time>+${String(t.offset).padStart(2,'0')}′</time><div><strong>${esc(t.title)}</strong><p>${esc(t.detail)}</p></div></div>`).join('')}<div class="question-card"><span class="overline">一个可以带着去的问题</span><p>“${esc(plan.question)}”</p></div><p class="hint" style="margin:16px 0 0">地点建议：${esc(plan.place)}。具体地点、营业时间、费用与分摊需双方确认。此提案未发送、未预约。</p></div></div>`;}
function createPlan(options){if(!state.profile)throw new Error('请先完成生活画像。');const plan=makePlan(state.profile,person(),options);state.options={...options};state.plan=plan;state.feedback='';state.step=2;state.furthest=2;render();return plan;}
function renderPlan(){const o=state.options;$('#app').innerHTML=`<div class="plan-layout reveal"><div class="match-header"><div><p class="overline">03 / TAKE IT INTO REAL LIFE</p><h3 tabindex="-1">给相遇，一个轻松的开始。</h3><p class="subtext">${esc(state.profile.name)} × ${person().name} · 先安排一次短见面，留给彼此选择的空间。</p></div></div><div class="plan-columns"><div class="plan-config"><form id="plan-form" novalidate>${selectField('type','一起做点什么',DATE_TYPES,o.type)}<div class="row-fields">${selectField('duration','留多少时间',[60,90],o.duration)}${selectField('budget','每人预算参考（元）',[80,150],o.budget)}</div>${selectField('meeting-city','见面城市',['双方另行商量','成都','上海','北京','广州','深圳','杭州'],o.city)}<div class="row-fields"><label class="field"><span>哪一天</span><input type="date" name="date" value="${esc(o.date)}" required></label><label class="field"><span>几点开始（本地时间）</span><input type="time" name="time" value="${esc(o.time)}" required></label></div><div class="notice">${esc(compare(state.profile,person()).hardConflict?'城市或婚育存在明确分歧，先讨论彼此期待，再决定是否见面。':'选交通方便的公共地点，给自己和对方一个舒适的结束时间。')}</div><div id="plan-error" class="error" role="alert"></div><div class="actions"><button class="button primary" type="submit">${state.plan?'更新':'生成'}见面提案 ↗</button><button class="button secondary" type="button" id="back-match">返回相处提案</button></div></form><div class="feedback"><h4>见面之后，听听自己的感受。</h4><p class="hint">在真实见面后可以用这三个问题做记录。当前仅用于体验，不发送给任何人。</p><div class="chips">${['还想再见','还需要了解','暂时不继续'].map(x=>`<button type="button" class="chip" data-feedback="${x}" aria-pressed="${state.feedback===x}">${x}</button>`).join('')}</div><p class="feedback-response" id="feedback-response" aria-live="polite">${esc(feedbackText(state.feedback))}</p></div></div><div><div id="plan-preview">${state.plan?planMarkup(state.plan):'<div class="profile-card empty-state"><span class="little-star" aria-hidden="true">✳</span><h4>一次见面，从一个小计划开始。</h4><p>选好活动与时间，再生成属于这次相遇的提案。</p></div>'}</div><div class="actions" id="plan-exports" ${state.plan?'':'hidden'}><button class="button secondary" type="button" id="copy-plan">复制提案</button><button class="button secondary" type="button" id="download-plan">下载文案</button><button class="link-button" type="button" id="calendar">导出日历草稿 ↗</button></div><p class="hint">日历仅下载到你的设备，不会向任何人发送邀请。</p></div></div></div>`;
 $('#plan-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements;try{createPlan({type:f.type.value,duration:Number(f.duration.value),budget:Number(f.budget.value),date:f.date.value,time:f.time.value,city:f['meeting-city'].value});toast('见面提案已更新。');}catch(error){$('#plan-error').textContent=error.message;}};
 $('#plan-form').onchange=()=>{if(state.plan){$('#plan-exports').hidden=true;$('#plan-preview').innerHTML='<div class="notice">选项已修改。点击“更新见面提案”后，再导出新版本。</div>';}};
 $('#back-match').onclick=()=>navigate(1,true);$('#copy-plan').onclick=()=>{if(state.plan)copyText(planText(state.profile,person(),state.plan));};$('#download-plan').onclick=()=>{if(state.plan){exportFile('有共鸣-见面提案.txt',planText(state.profile,person(),state.plan));toast('已下载见面提案。');}};$('#calendar').onclick=()=>{if(state.plan){exportFile('有共鸣-见面草稿.ics',calendar(state.plan),'text/calendar;charset=utf-8');toast('已导出日历草稿，尚未邀请任何人。');}};
 document.querySelectorAll('[data-feedback]').forEach(b=>b.onclick=()=>{state.feedback=b.dataset.feedback;document.querySelectorAll('[data-feedback]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#feedback-response').textContent=feedbackText(state.feedback);});
}
function feedbackText(value){return {'还想再见':'是什么具体的小瞬间，让你想继续了解？下次想一起做什么？','还需要了解':'还有哪个问题没有答案？想再见一次确认，还是先聊清楚？','暂时不继续':'是什么让你觉得不合适？温和表达结束，不需要说服自己。'}[value]||'';}
function navigate(step,focus=false){if(step>state.furthest)return;if(state.step===0)readDraft();state.step=step;render();if(focus){$('#experience').scrollIntoView({behavior:'smooth'});$('#app h3')?.focus({preventScroll:true});}}
function render(){document.querySelectorAll('.step').forEach((b,i)=>{b.disabled=i>state.furthest;b.classList.toggle('active',i===state.step);if(i===state.step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});if(state.step===0)renderProfile();if(state.step===1)renderMatch();if(state.step===2)renderPlan();}
document.querySelectorAll('.step').forEach(b=>b.onclick=()=>navigate(Number(b.dataset.step),true));$('#reset').onclick=()=>{state=fresh();render();toast('页面输入已清除，恢复虚构示例。');};render();
// WebMCP uses the same validated actions as the visible application, with no network calls.
const lifecycle=new AbortController();const context=document.modelContext;
function ensureObject(x){if(!x||typeof x!=='object'||Array.isArray(x))throw new Error('输入必须是对象。');}
const definitions=[
{name:'read_resonance_state',title:'读取当前体验状态',description:'读取当前步骤、已确认的画像、选中的虚构人物与见面草稿；不上传或导出任何内容。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){ensureObject(input);if(Object.keys(input).length)throw new Error('不接受额外字段。');return {step:state.step,profile:state.profile,person:person(),plan:state.plan};}},
{name:'set_resonance_profile',title:'确认生活画像',description:'校验并替换当前页面中的生活画像，清除旧提案并打开相处比较；数据只在当前页面内存。',inputSchema:{type:'object',properties:{name:{type:'string',minLength:1,maxLength:16},intro:{type:'string',minLength:12,maxLength:1200},city:{type:'string',enum:['成都','上海','北京','广州','深圳','杭州','其他 / 未定']},rhythm:{type:'string',enum:['偏早睡','偏晚睡','时间弹性']},children:{type:'string',enum:['希望养育孩子','不打算养育孩子','还没想好']},communication:{type:'string',enum:['愿意及时沟通','需要一点独处再聊','一起商量方式']},interests:{type:'array',items:{type:'string',enum:INTERESTS}}},required:['name','intro','city','rhythm','children','communication','interests'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){ensureObject(input);if(Object.keys(input).some(k=>!Object.keys(DEFAULT_PROFILE).includes(k)))throw new Error('不接受额外字段。');const p=commitProfile(input);state.step=1;render();return {step:1,profile:p,portrait:portrait(p)};}},
{name:'select_example_person',title:'切换虚构比较对象',description:'切换示例人物并显示相处提案，清除旧见面计划；不会联系任何真实用户。',inputSchema:{type:'object',properties:{id:{type:'string',enum:['xia','zhou']}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){ensureObject(input);if(Object.keys(input).some(k=>k!=='id'))throw new Error('不接受额外字段。');if(!state.profile)throw new Error('请先确认画像。');if(!PEOPLE.some(x=>x.id===input.id))throw new Error('示例人物不存在。');state.step=1;const result=choosePerson(input.id);render();return result;}},
{name:'create_meeting_draft',title:'生成本地见面草稿',description:'校验选项后生成并显示见面草稿；不预约地点、不发送邀请、不创建外部日历事件。',inputSchema:{type:'object',properties:{type:{type:'string',enum:DATE_TYPES},duration:{type:'number',enum:[60,90]},budget:{type:'number',enum:[80,150]},city:{type:'string',enum:['双方另行商量','成都','上海','北京','广州','深圳','杭州']},date:{type:'string',pattern:'^\\d{4}-\\d{2}-\\d{2}$'},time:{type:'string',pattern:'^\\d{2}:\\d{2}$'}},required:['type','duration','budget','city','date','time'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){ensureObject(input);if(Object.keys(input).some(k=>!['type','duration','budget','city','date','time'].includes(k)))throw new Error('不接受额外字段。');return createPlan(input);}}
];
if(context?.registerTool){for(const tool of definitions){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
